         color: var(--muted);
         line-height: 1.6;
       }

       form {
         margin-top: 28px;
       }

       .form-field {
         padding: 20px;
         border: 1px solid rgba(148, 163, 184, 0.22);
         border-radius: 18px;
         background: rgba(255, 255, 255, 0.7);
       }

       .question {
         margin: 0 0 16px;
         font-size: 1.05rem;
         font-weight: 650;
       }

       .options {
         display: grid;
         gap: 12px;
       }

       .option {
         display: flex;
         align-items: center;
         gap: 12px;
         padding: 14px 16px;
         border: 1px solid rgba(148, 163, 184, 0.24);
         border-radius: 14px;
         background: #fff;
         cursor: pointer;
         transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
       }

       .option:hover {
         border-color: rgba(37, 99, 235, 0.35);
         box-shadow: 0 8px 24px rgba(15, 23, 42, 0.06);
         transform: translateY(-1px);
       }

       .option input {
         width: 18px;
         height: 18px;
         accent-color: var(--primary);
         margin: 0;
       }

       .option span {
         font-size: 0.98rem;
         font-weight: 500;
       }

       .actions {
         margin-top: 18px;
         display: flex;
         justify-content: flex-end;
       }

       .submit {
         appearance: none;
         border: none;
         border-radius: 999px;
         padding: 12px 20px;
         font: inherit;
         font-weight: 700;
         color: #fff;
         background: linear-gradient(135deg, var(--primary), var(--primary-strong));
         box-shadow: 0 12px 24px rgba(37, 99, 235, 0.22);
         cursor: pointer;
       }

       .submit:focus-visible,
       .option input:focus-visible {
         outline: 3px solid var(--ring);
         outline-offset: 3px;
       }

       .submit:hover {
         filter: brightness(1.03);
       }

       .result {
         margin-top: 16px;
         color: var(--muted);
         min-height: 1.5em;
       }

       @media (max-width: 640px) {
         .card {
           padding: 22px;
           border-radius: 20px;
         }

         .form-field {
           padding: 16px;
         }

         .actions {
           justify-content: stretch;
         }

         .submit {
           width: 100%;
         }
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       const h = (tag, attrs = {}, children = []) => {
         const element = document.createElement(tag);
         Object.entries(attrs).forEach(([key, value]) => {
           if (key === "className") {
             element.className = value;
           } else if (key === "textContent") {
             element.textContent = value;
           } else if (key.startsWith("on") && typeof value === "function") {
             element.addEventListener(key.slice(2).toLowerCase(), value);
           } else if (value !== false && value != null) {
             element.setAttribute(key, value === true ? "" : value);
           }
         });
         children.flat().forEach((child) => {
           element.append(child.nodeType ? child : document.createTextNode(child));
         });
         return element;
       };

       function RadioOption({ id, name, value, label, checked = false }) {
         const input = h("input", {
           type: "radio",
           id,
           name,
           value,
           checked,
         });

         return h(
           "label",
           { className: "option", for: id },
           [input, h("span", { textContent: label })]
         );
       }

       function NotificationQuestion() {
         return h("div", { className: "form-field" }, [
           h("p", { className: "question", textContent: "How do you prefer to receive notifications?" }),
           h("div", { className: "options", role: "radiogroup", "aria-label": "Notification preference" }, [
             RadioOption({
               id: "notify-email",
               name: "notification-preference",
               value: "Email",
               label: "Email",
               checked: true,
             }),
             RadioOption({
               id: "notify-sms",
               name: "notification-preference",
               value: "SMS",
               label: "SMS",
             }),
             RadioOption({
               id: "notify-push",
               name: "notification-preference",
               value: "Push Notifications",
               label: "Push Notifications",
             }),
           ]),
         ]);
       }

       function App() {
         const result = h("p", { className: "result", id: "result", "aria-live": "polite" });
         const form = h("form", { novalidate: true }, [
           NotificationQuestion(),
           h("div", { className: "actions" }, [
             h("button", { className: "submit", type: "submit", textContent: "Submit" }),
           ]),
           result,
         ]);

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           const selected = form.querySelector('input[name="notification-preference"]:checked');
           result.textContent = selected
             ? `You chose ${selected.value}.`
             : "Please choose a notification preference.";
         });

         return h("main", { className: "page" }, [
           h("section", { className: "card", "aria-labelledby": "page-title" }, [
             h("p", { className: "eyebrow", textContent: "Preferences" }),
             h("h1", { id: "page-title", textContent: "Notification settings" }),
             h("p", {
               className: "description",
               textContent: "Choose one channel so we know how to keep you updated.",
             }),
             form,
           ]),
         ]);
       }

       document.getElementById("root").appendChild(App());
     </script>
   </body>
 </html>

')
